def main() -> None:
    golden_path = "data/golden/qa.jsonl"
    existing = [json.loads(l) for l in open(golden_path) if l.strip()]
    existing_ids = {e["id"] for e in existing}

    new = [e for e in ENTRIES if e["id"] not in existing_ids]
    if not new:
        print("All entries already present.")
        return

    with open(golden_path, "a") as f:
        for e in new:
            f.write(json.dumps(e, ensure_ascii=False) + "\n")

    print(f"Appended {len(new)} entries. Total: {len(existing) + len(new)}")


if __name__ == "__main__":
    main()
